#!/usr/bin/env node
/**
 * SIWE Server — Sign-In With Ethereum authentication backend
 * Handles: nonce generation, signature verification, JWT session management
 *
 * Usage: node siwe-server.js [--port 3000] [--test]
 *
 * This is the Web3-native auth layer for the Pareto Dashboard.
 * Replaces: no auth / Basic Auth with SIWE + session keys.
 * Compatible with: MetaMask, WalletConnect, any EIP-4361 compliant wallet.
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// --- Configuration ---
const PORT = parseInt(process.argv.find(a => a.startsWith('--port='))?.split('=')[1] || process.env.AUTH_PORT || 3000);
const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(64).toString('hex');
const SESSION_DURATION_MS = 24 * 60 * 60 * 1000; // 24 hours
const SESSION_FILE = path.join(__dirname, '..', 'session-cache.json');
const GITIGNORE_SESSION = true;

// --- Session Cache (file-based, git-ignored) ---
let sessions = {};
if (fs.existsSync(SESSION_FILE)) {
    try {
        sessions = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
        // Clean expired sessions
        const now = Date.now();
        let cleaned = false;
        for (const [addr, s] of Object.entries(sessions)) {
            if (s.expiresAt < now) { delete sessions[addr]; cleaned = true; }
        }
        if (cleaned) saveSessions();
    } catch (e) { sessions = {}; }
}

